247	export async function createChatRun(
248	  raw: unknown,
249	  scope: ChatRunScope,
250	  options?: { databaseUrl?: string }
251	) {
252	  const input = ChatRunRequestSchema.parse(raw);
253	  const databaseUrl = resolveHolocronNonprodDatabaseUrl({
254	    databaseUrl: options?.databaseUrl,
255	    context: 'chat run create',
256	  });
257	  const sql = createSql(databaseUrl);
258	  try {
259	    const result = await sql.begin(async (tx) => {
260	      const existing = await tx<ChatRunRow[]>`
261	        SELECT * FROM chat_runs WHERE owner_scope = ${scope} AND request_id = ${input.requestId}
262	        LIMIT 1
263	      `;
264	      if (existing[0]) return { created: false, run: existing[0] };
265	
266	      const rows = await tx<ChatRunRow[]>`
267	        INSERT INTO chat_runs (id, owner_scope, request_id, conversation_id, role, message)
268	        VALUES (${randomUUID()}::uuid, ${scope}, ${input.requestId}, ${input.conversationId ?? null}, ${resolveChatSpecialistRole(input.msg)}, ${input.msg})
269	        ON CONFLICT (owner_scope, request_id) DO NOTHING
270	        RETURNING *
271	      `;
272	      const run = rows[0];
